contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address callee, bytes memory _data) public payable {
        require(true);
        bool reverted;
        try c.forward(callee, _data) { reverted = false; } catch { reverted = true; }
        // The internal call is (bool _s,) = callee.call(_data), which reverts if callee has no code or the called function reverts.
        // So the rule: forward reverts if and only if callee.call(_data) would revert.
        bool internalWouldRevert;
        try callee.call(_data) { internalWouldRevert = false; } catch { internalWouldRevert = true; }
        assert(reverted == internalWouldRevert);
    }
    receive() external payable {}
